\caption{Contrasting dynamics ($2{\times}3$ grid). \textbf{Top row:} 008d (CIVO), showing eval collapse, value explosion, entropy decrease. \textbf{Bottom row:} 008e\_v3 s1 ($\dt{=}1$ imagination), no CIVO (NVE ${\leq}\,0.6\times$, eval $96\%$ baseline).}
\label{fig:multiple_pathways}
\end{figure}

\paragraph{F7: Full-pathway gradient stopping shows mixed results.}
\looseness=-1 Full-SGS (exp\_018) detaches all non-KL gradients from $e_{\dt}$. Seed~1 shows partial mitigation (eval 448.3, NVE $1.66\times$; anecdotal, $n{=}1$); seed~2 collapses (neither seed achieves elimination; Appendix~\ref{sec:sgs_gradient_analysis}). Cross-environment validation on Cheetah confirms CIVO generalization (010b, NVE $8.27$--$108.52\times$); full-SGS yields 0/3 elimination. Removing the embedding eliminates CIVO on Cheetah (024b, NVE $< 0.2\times$). Targeted obs-decoder-only SGS (exp\_025/026) achieves 1/6 prevention (1/4 Walker, 0/2 Cheetah; Table~\ref{tab:intervention_hierarchy}), confirming pathway redundancy: blocking any single channel shifts co-adaptation to the remaining ones (Appendix~\ref{sec:seed_divergence}).

